package io.xeros.solo;
import io.xeros.*;import io.xeros.content.combat.*;import io.xeros.content.combat.core.*;import io.xeros.content.combat.specials.impl.*;import io.xeros.model.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.npc.stats.*;import io.xeros.model.entity.player.*;import java.util.*;
public class Soulshot69Check{static void ok(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[]args)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");Server.startServerless();HitDispatcher.rand=new Random(){public int nextInt(int n){return n-1;}public double nextDouble(){return .99;}};for(int id:new int[]{6724,859}){Player p=WeaponsEquipment69Check.actor();p.playerEquipment[3]=id;p.playerEquipmentN[3]=1;p.playerEquipment[13]=892;p.playerEquipmentN[13]=2;p.playerBonus[Bonus.RANGED_STRENGTH.ordinal()]=1000;p.setSpellId(-1);p.autocasting=false;p.usingSpecial=true;p.specAmount=10;NpcCombatDefinition.definitions.get(Npcs.GOBLIN).setLevel(NpcCombatSkill.MAGIC,100);NPC n=new NPC(Npcs.GOBLIN,new Position(p.getX()+1,p.getY(),p.getHeight()));n.getHealth().setMaximumHealth(5000);n.getHealth().reset();p.attacking.attackEntity(n);ok(p.specAmount==0&&p.playerEquipmentN[13]==1&&p.getDamageQueue().getQueue().size()==1,"One arrow, one hit, all special energy "+id);int damage=p.getDamageQueue().getQueue().peek().getAmount();ok(damage==Soulshot.max(p),"Equipment/prayer must not boost Soulshot");for(int i=0;i<12;i++)p.getDamageQueue().execute();ok(n.getHealth().getCurrentHealth()<5000,"Guaranteed accuracy");ok(n.getCombatDefinition().getLevel(NpcCombatSkill.MAGIC)==(id==6724?100-damage:100),"Seercull drain vs longbow");n.unregisterInstant();ToaSoloPlayableCheck.clear(p);}System.out.println("SEERCULL_MAGIC_LONGBOW_NATIVE_SPECIAL_FULL_COST_SINGLE_ARROW_GUARANTEED_HIT_AMMO_ONLY_MAX_AND_MAGIC_DRAIN_PASS");System.exit(0);}}
